pair Cc=(10,5);
pair P1=(110,5),P2=(10,105),P3=(-90,5),P4=(10,-95);
fill(P1--P2--P3--P4--cycle,paleblue);draw(P1--P2--P3--P4--cycle,blue+linewidth(0.9));
draw((-110,0)--(135,0),Arrow);draw((0,-110)--(0,130),Arrow);
