size(7cm);
defaultpen(fontsize(10pt));
pair B=(0,0),C=(7,0);
real Bb=70,Cg=50;
pair A=extension(B,B+dir(Bb),C,C+dir(180-Cg));
pair P=extension(B,B+dir(Bb-20),C,C+dir(180-Cg+15));
draw(A--B--C--cycle,linewidth(0.9));
draw(B--P--C,blue+linewidth(0.8));
